DELIMITER $$

--
-- Create procedure `sp_menus`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_menus (IN p_accion varchar(50),
IN p_id int,
IN p_modulo_id int,
IN p_nombre varchar(100),
IN p_pagina_url varchar(200),
IN p_icono varchar(50),
IN p_orden int,
IN p_estado char(1))
BEGIN
  IF p_accion = 'CONSULTAR' THEN

    IF p_id IS NOT NULL
      AND p_id > 0 THEN

      SELECT
        m.id,
        m.modulo_id,
        mo.nombre AS modulo_nombre,
        m.nombre,
        m.pagina_url,
        m.icono,
        m.orden,
        m.estado
      FROM menus AS m
        INNER JOIN modulos AS mo
          ON m.modulo_id = mo.id
      WHERE m.id = p_id;

    ELSE

      SELECT
        m.id,
        m.modulo_id,
        mo.nombre AS modulo_nombre,
        m.nombre,
        m.pagina_url,
        m.icono,
        m.orden,
        m.estado
      FROM menus AS m
        INNER JOIN modulos AS mo
          ON m.modulo_id = mo.id
      ORDER BY mo.orden ASC, m.orden ASC;

    END IF;

  ELSEIF p_accion = 'CONSULTAR_POR_MODULO' THEN

    SELECT
      m.id,
      m.modulo_id,
      m.nombre,
      m.pagina_url,
      m.icono,
      m.orden,
      m.estado
    FROM menus AS m
    WHERE m.modulo_id = p_modulo_id
    AND m.estado = 'A'
    ORDER BY m.orden ASC;

  ELSEIF p_accion = 'INSERTAR' THEN

    INSERT INTO menus (modulo_id,
    nombre,
    pagina_url,
    icono,
    orden,
    estado)
      VALUES (
      p_modulo_id,
      p_nombre,
      p_pagina_url,
      COALESCE(p_icono, 'fas fa-file-alt'),
      COALESCE(p_orden, 0),
      COALESCE(p_estado, 'A')
      );

    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'EDITAR' THEN

    UPDATE menus
    SET modulo_id = p_modulo_id,
        nombre = p_nombre,
        pagina_url = p_pagina_url,
        icono = p_icono,
        orden = p_orden,
        estado = p_estado
    WHERE id = p_id;

    SELECT
      p_id AS id;

  ELSEIF p_accion = 'ELIMINAR' THEN

    DELETE
      FROM menus
    WHERE id = p_id;

    SELECT
      p_id AS id;

  END IF;
END
$$

