REFERENCES usuarios (id) ON DELETE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_usuario_permisos`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_usuario_permisos (IN p_accion varchar(50),
IN p_id int,
IN p_usuario_id int,
IN p_modulo_id int,
IN p_menu_id int,
IN p_acceso tinyint)
BEGIN

  IF p_accion = 'CONSULTAR_MENU_TREE' THEN

    -- Construye el árbol dinámico de menú para el usuario logueado
    SELECT
      mo.id AS modulo_id,
      mo.codigo AS modulo_codigo,
      mo.nombre AS modulo_nombre,
      mo.icono AS modulo_icono,
      m.id AS menu_id,
      m.nombre AS menu_nombre,
      m.pagina_url AS menu_pagina_url,
      m.icono AS menu_icono
    FROM usuario_permisos AS up
      INNER JOIN modulos AS mo
        ON up.modulo_id = mo.id
      INNER JOIN menus AS m
        ON up.menu_id = m.id
    WHERE up.usuario_id = p_usuario_id
    AND up.acceso = 1
    AND mo.estado = 'A'
    AND m.estado = 'A'
    ORDER BY mo.orden ASC, m.orden ASC;

  ELSEIF p_accion = 'CONSULTAR_PERMISOS_USUARIO' THEN

    SELECT
      up.id,
      up.usuario_id,
      up.modulo_id,
      up.menu_id,
      up.acceso,
      mo.nombre AS modulo_nombre,
      m.nombre AS menu_nombre
    FROM usuario_permisos AS up
      INNER JOIN modulos AS mo
        ON up.modulo_id = mo.id
      INNER JOIN menus AS m
        ON up.menu_id = m.id
    WHERE up.usuario_id = p_usuario_id;

  ELSEIF p_accion = 'ASIGNAR_PERMISO' THEN

    INSERT INTO usuario_permisos (usuario_id,
    modulo_id,
    menu_id,
    acceso)
      VALUES (
      p_usuario_id,
      p_modulo_id,
      p_menu_id,
      COALESCE(p_acceso, 1)
      )
    ON DUPLICATE KEY UPDATE
    acceso = COALESCE(p_acceso, 1);

    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'REVOCAR_TODOS_USUARIO' THEN

    DELETE
      FROM usuario_permisos
    WHERE usuario_id = p_usuario_id;

    SELECT
      p_usuario_id AS id;

  END IF;

END
$$

DELIMITER ;

