--
-- Create procedure `sp_usuario_empresas`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_usuario_empresas (IN p_accion varchar(50),
IN p_usuario_id int,
IN p_empresa_id int)
BEGIN
  IF p_accion = 'CONSULTAR' THEN
    SELECT
      ue.id,
      ue.usuario_id,
      u.username,
      u.nombre_completo,
      ue.empresa_id,
      e.razon_social
    FROM usuario_empresas ue
      INNER JOIN usuarios u
        ON ue.usuario_id = u.id
      INNER JOIN empresas e
        ON ue.empresa_id = e.id
    WHERE (p_usuario_id IS NULL
    OR ue.usuario_id = p_usuario_id);

  ELSEIF p_accion = 'ASIGNAR' THEN
    INSERT INTO usuario_empresas (usuario_id, empresa_id)
      VALUES (p_usuario_id, p_empresa_id)
    ON DUPLICATE KEY UPDATE empresa_id = p_empresa_id;
    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'ELIMINAR' THEN
    DELETE
      FROM usuario_empresas
    WHERE usuario_id = p_usuario_id
      AND empresa_id = p_empresa_id;
    SELECT
      p_usuario_id AS id;

  ELSEIF p_accion = 'ELIMINAR_TODAS_DE_USUARIO' THEN
    DELETE
      FROM usuario_empresas
    WHERE usuario_id = p_usuario_id;
    SELECT
      p_usuario_id AS id;
  END IF;
END
$$

--
-- Create procedure `sp_empresas`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_empresas (IN p_accion varchar(50),
IN p_id int,
IN p_ruc varchar(15),
IN p_razon_social varchar(200),
IN p_direccion varchar(250),
IN p_telefono varchar(20),
IN p_estado char(1),
IN p_usuario_id int)
BEGIN
  IF p_accion = 'CONSULTAR' THEN
    IF p_id IS NOT NULL
      AND p_id > 0 THEN
      SELECT
        id,
        ruc,
        razon_social,
        direccion,
        telefono,
        estado,
        created_at
      FROM empresas
      WHERE id = p_id;
    ELSE
      SELECT
        id,
        ruc,
        razon_social,
        direccion,
        telefono,
        estado,
        created_at
      FROM empresas
      ORDER BY id DESC;
    END IF;

  ELSEIF p_accion = 'CONSULTAR_POR_USUARIO' THEN
    SELECT
      e.id,
      e.ruc,
      e.razon_social,
      e.direccion,
      e.telefono,
      e.estado
    FROM empresas e
      INNER JOIN usuario_empresas ue
        ON e.id = ue.empresa_id
    WHERE ue.usuario_id = p_usuario_id
    AND e.estado = 'A';

  ELSEIF p_accion = 'INSERTAR' THEN
    INSERT INTO empresas (ruc, razon_social, direccion, telefono, estado)
      VALUES (p_ruc, p_razon_social, p_direccion, p_telefono, COALESCE(p_estado, 'A'));
    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'EDITAR' THEN
    UPDATE empresas
    SET ruc = p_ruc,
        razon_social = p_razon_social,
        direccion = p_direccion,
        telefono = p_telefono,
        estado = p_estado
    WHERE id = p_id;
    SELECT
      p_id AS id;

  ELSEIF p_accion = 'ELIMINAR' THEN
    DELETE
      FROM empresas
    WHERE id = p_id;
    SELECT
      p_id AS id;
  END IF;
END
$$

DELIMITER ;

