DELIMITER $$

--
-- Create procedure `sp_empresa_periodos`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_empresa_periodos (IN p_accion varchar(50),
IN p_id int,
IN p_empresa_id int,
IN p_anio int,
IN p_mes int,
IN p_estado char(1))
BEGIN
  IF p_accion = 'CONSULTAR' THEN
    IF p_id IS NOT NULL
      AND p_id > 0 THEN
      SELECT
        ep.id,
        ep.empresa_id,
        e.razon_social AS empresa_nombre,
        ep.anio,
        ep.mes,
        ep.estado,
        ep.created_at
      FROM empresa_periodos ep
        INNER JOIN empresas e
          ON ep.empresa_id = e.id
      WHERE ep.id = p_id;
    ELSE
      SELECT
        ep.id,
        ep.empresa_id,
        e.razon_social AS empresa_nombre,
        ep.anio,
        ep.mes,
        ep.estado,
        ep.created_at
      FROM empresa_periodos ep
        INNER JOIN empresas e
          ON ep.empresa_id = e.id
      ORDER BY ep.anio DESC, ep.mes DESC, ep.empresa_id ASC;
    END IF;

  ELSEIF p_accion = 'CONSULTAR_ANIOS_POR_EMPRESA' THEN
    SELECT DISTINCT
      anio
    FROM empresa_periodos
    WHERE empresa_id = p_empresa_id
    AND estado = 'A'
    ORDER BY anio DESC;

  ELSEIF p_accion = 'CONSULTAR_MESES_POR_EMPRESA_ANIO' THEN
    SELECT
      mes,
      estado
    FROM empresa_periodos
    WHERE empresa_id = p_empresa_id
    AND anio = p_anio
    ORDER BY mes ASC;

  ELSEIF p_accion = 'INSERTAR' THEN
    INSERT INTO empresa_periodos (empresa_id, anio, mes, estado)
      VALUES (p_empresa_id, p_anio, p_mes, COALESCE(p_estado, 'A'));
    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'EDITAR' THEN
    UPDATE empresa_periodos
    SET empresa_id = p_empresa_id,
        anio = p_anio,
        mes = p_mes,
        estado = p_estado
    WHERE id = p_id;
    SELECT
      p_id AS id;

  ELSEIF p_accion = 'ELIMINAR' THEN
    DELETE
      FROM empresa_periodos
    WHERE id = p_id;
    SELECT
      p_id AS id;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `clientes`
--
CREATE TABLE clientes (
  id int(11) NOT NULL AUTO_INCREMENT,
  empresa_id int(11) NOT NULL,
  codigo varchar(20) NOT NULL,
  tipo_entidad varchar(20) DEFAULT 'CLIENTE',
  razon_social varchar(200) NOT NULL,
  direccion varchar(250) DEFAULT '',
  ruc_dni varchar(20) DEFAULT '',
  representante varchar(100) DEFAULT '',
  tipo_doc varchar(10) DEFAULT 'RUC',
  estado char(1) DEFAULT 'A',
  created_at datetime DEFAULT CURRENT_TIMESTAMP(),
  updated_at datetime DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 4,
AVG_ROW_LENGTH = 5461,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create foreign key
--
ALTER TABLE clientes
ADD CONSTRAINT fk_cliente_empresa FOREIGN KEY (empresa_id)
REFERENCES empresas (id) ON DELETE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_clientes`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_clientes (IN p_accion varchar(50),
IN p_id int,
IN p_empresa_id int,
IN p_codigo varchar(20),
IN p_tipo_entidad varchar(20),
IN p_razon_social varchar(200),
IN p_direccion varchar(250),
IN p_ruc_dni varchar(20),
IN p_representante varchar(100),
IN p_tipo_doc varchar(10),
IN p_estado char(1))
BEGIN
  IF p_accion = 'CONSULTAR' THEN
    IF p_id IS NOT NULL
      AND p_id > 0 THEN
      SELECT
        c.*,
        e.razon_social AS empresa_nombre
      FROM clientes c
        LEFT JOIN empresas e
          ON c.empresa_id = e.id
      WHERE c.id = p_id;
    ELSE
      SELECT
        c.*,
        e.razon_social AS empresa_nombre
      FROM clientes c
        LEFT JOIN empresas e
          ON c.empresa_id = e.id
      WHERE (p_empresa_id IS NULL
      OR c.empresa_id = p_empresa_id)
      AND c.estado = 'A'
      ORDER BY c.id DESC;
    END IF;

  ELSEIF p_accion = 'CONSULTAR_CLIENTES_DE_BAJA' THEN
    -- Acción personalizada dentro del mismo SP para clientes inactivados/de baja
    SELECT
      c.*,
      e.razon_social AS empresa_nombre
    FROM clientes c
      LEFT JOIN empresas e
        ON c.empresa_id = e.id
    WHERE (p_empresa_id IS NULL
    OR c.empresa_id = p_empresa_id)
    AND c.estado = 'B'
    ORDER BY c.id DESC;

  ELSEIF p_accion = 'INSERTAR' THEN
    INSERT INTO clientes (empresa_id, codigo, tipo_entidad, razon_social, direccion, ruc_dni, representante, tipo_doc, estado)
      VALUES (p_empresa_id, p_codigo, COALESCE(p_tipo_entidad, 'CLIENTE'), p_razon_social, p_direccion, p_ruc_dni, p_representante, COALESCE(p_tipo_doc, 'RUC'), COALESCE(p_estado, 'A'));
    SELECT
      LAST_INSERT_ID() AS id;

  ELSEIF p_accion = 'EDITAR' THEN
    UPDATE clientes
    SET empresa_id = p_empresa_id,
        codigo = p_codigo,
        tipo_entidad = p_tipo_entidad,
        razon_social = p_razon_social,
        direccion = p_direccion,
        ruc_dni = p_ruc_dni,
        representante = p_representante,
        tipo_doc = p_tipo_doc,
        estado = p_estado
    WHERE id = p_id;
    SELECT
      p_id AS id;

  ELSEIF p_accion = 'ELIMINAR' THEN
    DELETE
      FROM clientes
    WHERE id = p_id;
    SELECT
      p_id AS id;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `configuracion_framework`
--
CREATE TABLE configuracion_framework (
  id int(11) NOT NULL AUTO_INCREMENT,
  tema_color varchar(50) DEFAULT 'rojo-granate',
  nombre_sistema varchar(100) DEFAULT 'ADVISOR-ERP',
  created_at datetime DEFAULT CURRENT_TIMESTAMP(),
  updated_at datetime DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 2,
AVG_ROW_LENGTH = 16384,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `sp_configuracion`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE sp_configuracion (IN p_accion varchar(50),
IN p_tema_color varchar(50),
IN p_nombre_sistema varchar(100))
BEGIN
  IF p_accion = 'CONSULTAR' THEN
    SELECT
      id,
      tema_color,
      nombre_sistema,
      updated_at
    FROM configuracion_framework
    WHERE id = 1;

  ELSEIF p_accion = 'ACTUALIZAR' THEN
    UPDATE configuracion_framework
    SET tema_color = COALESCE(p_tema_color, tema_color),
        nombre_sistema = COALESCE(p_nombre_sistema, nombre_sistema)
    WHERE id = 1;
    SELECT
      1 AS id;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `CNM_ENTIDAD`
--
CREATE TABLE CNM_ENTIDAD (
  Emp_cCodigo char(3) NOT NULL,
  Ent_cCodEntidad varchar(20) NOT NULL,
  Ten_cTipoEntidad char(1) NOT NULL DEFAULT 'C',
  Ent_cPersona varchar(120) NOT NULL,
  Ent_cDireccion varchar(120) DEFAULT '',
  Ent_nRuc varchar(15) DEFAULT '',
  Ent_cRepresentante varchar(80) DEFAULT '',
  Ent_cTipoDoc char(3) DEFAULT 'RUC',
  Ent_cFlagPersona char(1) DEFAULT 'J',
  Ent_cEstadoEntidad char(1) DEFAULT '1',
  Ent_cEstado char(1) DEFAULT 'A',
  Ent_cDeleted char(1) DEFAULT '',
  Ent_cUserCrea varchar(20) DEFAULT '',
  Ent_dFechaCrea datetime DEFAULT CURRENT_TIMESTAMP(),
  Ent_cUserModifica varchar(20) DEFAULT NULL,
  Ent_dFechaModifica datetime DEFAULT NULL,
  Ent_cEquipoUser varchar(50) DEFAULT '',
  Ent_ValidaLC char(1) DEFAULT '0',
  PRIMARY KEY (Emp_cCodigo, Ten_cTipoEntidad, Ent_cCodEntidad)
)
ENGINE = INNODB,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_uca1400_ai_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `spClientes`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE spClientes (IN p_Accion varchar(20),
IN p_Emp_cCodigo char(3),
IN p_Ent_cCodEntidad varchar(20),
IN p_Ten_cTipoEntidad char(1),
IN p_Ent_cPersona varchar(120),
IN p_Ent_cDireccion varchar(120),
IN p_Ent_nRuc varchar(15),
IN p_Ent_cRepresentante varchar(80),
IN p_Ent_cTipoDoc char(3),
IN p_Ent_cFlagPersona char(1),
IN p_Ent_cEstadoEntidad char(1),
IN p_Ent_cEstado char(1),
IN p_Ent_cDeleted char(1),
IN p_Ent_cUserCrea varchar(20),
IN p_Ent_cUserModifica varchar(20),
IN p_Ent_ValidaLC char(1))
BEGIN
  IF p_Accion = 'INSERTAR' THEN
    INSERT INTO CNM_ENTIDAD (Emp_cCodigo, Ent_cCodEntidad, Ten_cTipoEntidad, Ent_cPersona,
    Ent_cDireccion, Ent_nRuc, Ent_cRepresentante, Ent_cTipoDoc,
    Ent_cFlagPersona, Ent_cEstadoEntidad, Ent_cEstado, Ent_cDeleted,
    Ent_cUserCrea, Ent_dFechaCrea, Ent_cEquipoUser, Ent_ValidaLC)
      VALUES (
      p_Emp_cCodigo, p_Ent_cCodEntidad, p_Ten_cTipoEntidad, p_Ent_cPersona,
      p_Ent_cDireccion, p_Ent_nRuc, p_Ent_cRepresentante, p_Ent_cTipoDoc,
      p_Ent_cFlagPersona, '1', 'A', p_Ent_cDeleted,
      p_Ent_cUserCrea, NOW(), USER(), p_Ent_ValidaLC
      );

  ELSEIF p_Accion = 'VALIDALC' THEN
    SELECT
      COALESCE(CE.Ent_ValidaLC, '0') AS Ent_ValidaLC
    FROM CNM_ENTIDAD CE
    WHERE CE.Emp_cCodigo = p_Emp_cCodigo
    AND CE.Ten_cTipoEntidad = p_Ten_cTipoEntidad
    AND CE.Ent_cCodEntidad = p_Ent_cCodEntidad;

  ELSEIF p_Accion = 'EDITAR' THEN
    UPDATE CNM_ENTIDAD
    SET Ent_cPersona = p_Ent_cPersona,
        Ent_cDireccion = p_Ent_cDireccion,
        Ent_nRuc = p_Ent_nRuc,
        Ent_cRepresentante = p_Ent_cRepresentante,
        Ent_cTipoDoc = p_Ent_cTipoDoc,
        Ent_cFlagPersona = p_Ent_cFlagPersona,
        Ent_cEstadoEntidad = '1',
        Ent_cEstado = 'A',
        Ent_cDeleted = p_Ent_cDeleted,
        Ent_cUserModifica = p_Ent_cUserModifica,
        Ent_dFechaModifica = NOW(),
        Ent_cEquipoUser = USER(),
        Ent_ValidaLC = p_Ent_ValidaLC
    WHERE Emp_cCodigo = p_Emp_cCodigo
    AND Ten_cTipoEntidad = p_Ten_cTipoEntidad
    AND Ent_cCodEntidad = p_Ent_cCodEntidad;

  ELSEIF p_Accion = 'ELIMINAR' THEN
    DELETE
      FROM CNM_ENTIDAD
    WHERE Emp_cCodigo = p_Emp_cCodigo
      AND Ten_cTipoEntidad = p_Ten_cTipoEntidad
      AND Ent_cCodEntidad = p_Ent_cCodEntidad;

  ELSEIF p_Accion = 'BUSCARREGISTRO' THEN
    SELECT
      *
    FROM CNM_ENTIDAD
    WHERE Emp_cCodigo = p_Emp_cCodigo
    AND Ten_cTipoEntidad = p_Ten_cTipoEntidad
    AND Ent_cCodEntidad = p_Ent_cCodEntidad;

  ELSEIF p_Accion = 'BUSCARTODOS' THEN
    SELECT
      Ent_cCodEntidad,
      Ent_cPersona
    FROM CNM_ENTIDAD
    WHERE Emp_cCodigo = p_Emp_cCodigo
    AND Ten_cTipoEntidad = p_Ten_cTipoEntidad;
  END IF;
END
$$

DELIMITER ;

